SELECT CASE WHEN qs.disabled THEN 'DISABLE' ELSE 'ENABLE' END as tabFlag, CASE WHEN qs.disabled THEN '已禁用' ELSE '已启用' END as tabFlagName, COUNT(qs.id) as count FROM qc_standard qs WHERE qs.is_deleted = false
${params.permissionSql}
GROUP BY qs.disabled

SELECT qs.* FROM qc_standard qs WHERE qs.is_deleted = false
${params.permissionSql}
ORDER BY qs.create_time DESC
